head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _6 : 기타 옵션(optionParam, trim, msaName). description 은 분리 샘플 공통.
//  ★ 전달값 확인을 위해 CSV 파일 선택 팝업창은 wframe(화면 내 레이어) 형태로 고정한다.
scwin.tData = {
    "description" : "[gridView > M > readCSV]<br/>CSV 형식의 파일을 업로드하여 GridView 의 데이터로 설정합니다.",
    "validation" : [
        "optionParam(선택) 파라미터로 파일 암호화(DRM) 연계 시 사용자 정의 Class 에 HashMap 인자로 전달할 값을 설정합니다.",
        "optionParam(선택) 파라미터는 서버에서 'optionParam' 키로 참조됩니다.",
        "optionParam(선택) 파라미터를 생략하면 기본값인 빈 문자열로 동작합니다.",
        "trim(선택) 파라미터로 CSV 데이터 설정 시 각 Column 데이터의 좌우 공백 제거 여부를 설정합니다.",
        "trim(선택) 파라미터를 '0' 으로 설정 시 Column 데이터의 좌우 공백을 유지합니다.",
        "trim(선택) 파라미터를 '1' 로 설정 시 Column 데이터의 좌우 공백을 제거합니다.",
        "trim(선택) 파라미터를 생략하면 기본값 '0' 으로 동작합니다.",
        "msaName(선택) 파라미터로 MSA 기능을 사용하는 경우 적용할 MSA 서버의 이름을 설정합니다.",
        "msaName(선택) 파라미터가 지정된 경우 해당 MSA 서버의 경로가 자동으로 URL 에 추가됩니다.",
        "msaName(선택) 파라미터를 생략하면 기본값인 빈 문자열로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : DataList 가 바인딩된 4 Column GridView 를 동적 생성한다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- name1~name4 4개 Column 그리드에 초기 데이터 4행(col1_1 ~ col4_4)이 바인딩되어 있음\n- 전달된 옵션값을 화면에서 확인할 수 있도록 업로드 창은 화면 내 레이어(wframe) 형태로 고정 실행됨\n- 테스트용 CSV : TSQA/src/sample/gridView/data/upload/ts_gridView_M_readCSV_6/ts_gridView_M_readCSV_6_upload.csv (0행 Header, 1~2행 데이터의 모든 값 좌우에 공백 2칸 포함)\n[절차]\n1. Target 재생성 버튼으로 그리드를 초기 4행 상태로 되돌린다\n2. par 옵션(optionParam / trim / msaName) 값을 선택한다\n3. readCSV 버튼을 클릭한다\n4. (trim 확인 시) 열린 레이어에서 CSV 파일을 선택하고 File Upload 를 실행한다\n5. (trim 확인 시) 업로드결과확인 버튼을 클릭한다\n[확인]\n- 3번 직후 결과창에 업로드 창에 실제 렌더된 optionParam / trim / msaName 값과 업로드 요청 URL 이 출력됨\n- optionParam 은 3번 출력의 전달값으로만 확인한다 - 미설정 시 optionParam : [] / 설정 시 optionParam : [optionParamTest] 로 대비되고, 전송 파라미터의 키 이름이 optionParam 인 것으로 서버에서 참조되는 키를 확인 (4~5번은 수행하지 않음)\n- msaName 은 3번 출력의 업로드 요청 URL 로만 확인한다 - 미설정 시 /websquare/csvToXML.wq, msa_server 설정 시 http://192.168.100.250:8080/csvToXML.wq 로 MSA 서버 경로가 자동으로 추가되는 것을 확인 (4~5번은 수행하지 않음)\n- trim 은 4~5번까지 수행하여 업로드 결과로 확인한다\n- 5번 출력은 값을 대괄호로 감싸 표시하므로 좌우 공백 유지/제거 여부를 확인"', '', 'label1');

    // DataList 생성 (col1~col4 / 4행)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (DataList 바인딩)
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id
    });
    await $c.gcm.createBasicGridView(cList);
}



// par 옵션값으로 readCSV options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · wframe 은 전달값 확인 수단이므로 항상 true 로 고정한다.
scwin.buildOptions = function () {
    let options = { wframe : true };
    let v;

    v = par_optionParam.getValue();
    if (v !== "") options.optionParam = v;

    v = par_trim.getValue();
    if (v !== "") options.trim = v;

    v = par_msaName.getValue();
    if (v !== "") options.msaName = v;

    return options;
}



// readCSV 실행
//  · 설정한 옵션값을 그대로 되출력하지 않고, 실제로 열린 CSV 파일 선택 업로드 창에 렌더된 값을 읽어 출력한다.
scwin.btn_readCSV_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    target1.readCSV(scwin.buildOptions());

    // 업로드 창이 렌더된 뒤 실제 반영값 확인
    setTimeout(scwin.printUploadParam, 1200);
}



// CSV 파일 선택 팝업창(레이어)으로 전달된 옵션값과 업로드 요청 URL 출력
scwin.printUploadParam = function (nRetry) {
    let bottom = wf_body_bottom.getObj("scwin");
    nRetry = nRetry || 0;

    let objOptionParam = document.querySelector("input[id$='_csvPop_wframe_optionParam']");
    let objTrim = document.querySelector("input[id$='_csvPop_wframe_trim']");
    let objMsaName = document.querySelector("input[id$='_csvPop_wframe_msaName']");
    let objForm = document.querySelector("form[name='__uploadForm__']");

    // 업로드 창은 비동기로 렌더되므로 필드가 아직 없으면 재시도한다.
    if (objOptionParam === null) {
        if (nRetry < 6) {
            setTimeout(function () { scwin.printUploadParam(nRetry + 1); }, 500);
            return;
        }
        bottom.setReturnValue("업로드 창이 열려있지 않아 실제 렌더값을 확인할 수 없습니다.");
        return;
    }

    bottom.setReturnValue("업로드 창 렌더값 - optionParam : [" + objOptionParam.value + "] / trim : [" + objTrim.value + "] / msaName : [" + objMsaName.value + "]");
    bottom.setReturnValue("업로드 요청 URL : " + (objForm === null ? "" : objForm.getAttribute("action")));
}



// 업로드 결과 확인 : 좌우 공백 확인을 위해 값을 대괄호로 감싸 출력한다.
scwin.btn_getResult_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("=====btn_getResult_onclick=====");

    let cnt = target1.getRowCount();
    bottom.setReturnValue("GridView Row 수 : " + cnt + " / 바인딩 DataList Row 수 : " + dlt_bind.getRowCount());
    for (let i = 0; i < cnt; i++) {
        bottom.setReturnValue("[" + i + "] [" + target1.getCellData(i, "col1") + "] [" + target1.getCellData(i, "col2") + "] [" + target1.getCellData(i, "col3") + "] [" + target1.getCellData(i, "col4") + "]");
    }
}
